cypress_script:
describe('Login Form', () => {
  it('should log in successfully with valid credentials', () => {
    cy.visit('https://the-internet.herokuapp.com/login');
    cy.get('#username').type('tomsmith');
    cy.get('#password').type('SuperSecretPassword!');
    cy.get('button.radius').click();
    cy.url().should('not.eq', 'https://the-internet.herokuapp.com/login');
  });

  it('should not log in with empty credentials', () => {
    cy.visit('https://the-internet.herokuapp.com/login');
    cy.get('button.radius').click();
    cy.url().should('eq', 'https://the-internet.herokuapp.com/login');
    cy.get('#flash-messages').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Login Form', () => {
  test('should log in successfully with valid credentials', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/login');
    await page.fill('#username', 'tomsmith');
    await page.fill('#password', 'SuperSecretPassword!');
    await page.click('button.radius');
    await expect(page).toHaveURL(/^(?!https://the-internet.herokuapp.com/login).*/);
  });

  test('should not log in with empty credentials', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/login');
    await page.click('button.radius');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/login');
    await expect(page.locator('#flash-messages')).toBeVisible();
  });
});
